<?php
session_start();
require_once './../public/libs/dompdf/autoload.inc.php'; 
use Dompdf\Dompdf;


if (!isset($_SESSION['reporte_data'])) {
    echo "No hay datos para mostrar.";
    exit;
}

$datos = $_SESSION['reporte_data'];
$fechas = $_SESSION['reporte_fechas'];
$producto = isset($_SESSION['reporte_producto']) ? $_SESSION['reporte_producto'] : 'Todos los productos';

// Empieza la construcción del HTML del PDF
$html = '

<meta charset="UTF-8">

<style>
    body {
        font-family: "DejaVu Sans", sans-serif;

        font-size: 12px;
        color: #333;
        padding: 30px;
    }

    h2 {
        text-align: center;
        color: #1a1a1a;
        margin-bottom: 5px;
    }

    p {
        text-align: center;
        margin: 2px 0;
        font-size: 13px;
    }

    table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 20px;
        box-shadow: 0 0 4px rgba(0, 0, 0, 0.2);
    }

    th {
        background-color: #004085;
        color: #fff;
        font-weight: bold;
        padding: 8px;
        border: 1px solid #ccc;
        font-size: 15px;
    }

    td {
        padding: 8px;
        border: 1px solid #ccc;
        font-size: 13px;
    }

    tr:nth-child(even) {
        background-color: #f9f9f9;
    }

    .footer {
        margin-top: 40px;
        text-align: right;
        font-size: 11px;
        color: #777;
    }
</style>

<img src="data:image/jpeg;base64," width="80" style="display: block; margin: 0 auto 20px auto; width: 140px; height: auto;">


<h2>Reporte de Entradas y Salidas de Inventario</h2>
<p><strong>Rango de fechas:</strong> ' . $fechas['inicio'] . ' al ' . $fechas['fin'] . '</p>
<p><strong>Producto:</strong> ' . $producto . '</p>

<table>
    <thead>
        <tr>
            <th>Producto</th>
            <th>Lote</th>
            <th>Talla</th>
            <th>Proveedor</th>
            <th>Entradas</th>
            <th>Salidas</th>
            <th>Fecha y Hora</th>
        </tr>
    </thead>
    <tbody>';


foreach ($datos as $row) {
    $html .= '<tr>
        <td>' . $row['producto'] . '</td>
        <td>' . $row['numero_lote'] . '</td>
        <td>' . $row['talla'] . '</td>
        <td>' . $row['proveedor'] . '</td>
        <td>' . $row['cantidad_entrada'] . '</td>
        <td>' . $row['cantidad_salida'] . '</td>
        <td>' . $row['fecha_hora'] . '</td>
    </tr>';
}

$html .= '</tbody></table>';

// Crear el PDF
$dompdf = new Dompdf();
$dompdf->loadHtml($html);
$dompdf->setPaper('A4', 'landscape'); // o portrait si prefieres
$dompdf->render();

// Descargar
$dompdf->stream("reporte_inventario_" . date('Ymd_His') . ".pdf", ["Attachment" => true]);

// Limpiar sesión para evitar que se descargue el mismo PDF luego
unset($_SESSION['reporte_data']);
unset($_SESSION['reporte_fechas']);